extern fn sqlite3_open(filename: [*:0]const u8, ppDb: **_sqlite3) c_int;
extern fn sqlite3_close_v2(db: *_sqlite3) c_int;
extern fn sqlite3_errmsg(db: *_sqlite3) [*:0]const u8;
