fn _sqlite_open(path: []const u8) ?SqliteDb {
    const cpath = _allocator.dupeZ(u8, path) catch return null;
    defer _allocator.free(cpath);
    var db_raw: *_sqlite3 = undefined;
    if (sqlite3_open(cpath, &db_raw) != _SQLITE_OK) {
        std.debug.print("Sqlite.open error: {s}\n", .{sqlite3_errmsg(db_raw)});
        _ = sqlite3_close_v2(db_raw);
        return null;
    }
    const s = _allocator.create(_SqliteDbInner) catch {
        _ = sqlite3_close_v2(db_raw);
        return null;
    };
    s.* = .{ .db = db_raw };
    return s;
}

pub fn _zbr_error_msg() []const u8 {
    if (_error_ctx.message.len > 0) return _error_ctx.message;
    if (@import("Parser.zig")._zbr_error_msg().len > 0) return @import("Parser.zig")._zbr_error_msg();
    if (@import("Resolver.zig")._zbr_error_msg().len > 0) return @import("Resolver.zig")._zbr_error_msg();
    if (@import("AstBuilder.zig")._zbr_error_msg().len > 0) return @import("AstBuilder.zig")._zbr_error_msg();
    if (@import("Ast.zig")._zbr_error_msg().len > 0) return @import("Ast.zig")._zbr_error_msg();
    if (@import("CodeGen.zig")._zbr_error_msg().len > 0) return @import("CodeGen.zig")._zbr_error_msg();
    if (@import("CgHelpers.zig")._zbr_error_msg().len > 0) return @import("CgHelpers.zig")._zbr_error_msg();
    if (@import("TypeChecker.zig")._zbr_error_msg().len > 0) return @import("TypeChecker.zig")._zbr_error_msg();
    if (@import("Checker.zig")._zbr_error_msg().len > 0) return @import("Checker.zig")._zbr_error_msg();
    return "";
}
