    if (std.mem.eql(u8, color, "yellow"))  return "\x1b[33m";
    if (std.mem.eql(u8, color, "blue"))    return "\x1b[34m";
    if (std.mem.eql(u8, color, "magenta")) return "\x1b[35m";
    if (std.mem.eql(u8, color, "cyan"))    return "\x1b[36m";
